const COLORS=['#cf303b','#f2ca46','#63a6df','#e8e8e8','#e2602c','#73c6a4','#916de0','#ee87aa','#89b54b','#f1f3ec'];
const allTeamNames=Object.values(LEAGUES).flat();
const teamPower=name=>{let n=0;for(let i=0;i<name.length;i++)n+=name.charCodeAt(i)*(i+13);return 67+n%27};
let career=null,selectedTeam='',selectedLeague='',sceneMode='home',activeMatch=null,keys={},clockLast=0,sceneReady=false;
const $=id=>document.getElementById(id);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function crestColor(name){return COLORS[name.split('').reduce((s,c)=>s+c.charCodeAt(0),0)%COLORS.length]}
function initializeSetup(){const select=$('leagueSelect');select.innerHTML=Object.keys(LEAGUES).map(l=>`<option value="${l}">${l}</option>`).join('');select.onchange=()=>renderTeams();renderTeams()}
function renderTeams(){selectedLeague=$('leagueSelect').value;const teams=LEAGUES[selectedLeague]||[];$('teamCount').textContent=`· ${teams.length} clubs`;$('teamList').innerHTML=teams.map(t=>`<button class="team-option ${selectedTeam===t?'active':''}" data-team="${t}"><span class="crest" style="--c:${crestColor(t)}">${t.split(/\s+/).slice(0,2).map(x=>x[0]).join('')}</span>${t}</button>`).join('');document.querySelectorAll('.team-option').forEach(b=>b.onclick=()=>{selectedTeam=b.dataset.team;renderTeams();updateScout()});if(!teams.includes(selectedTeam))selectedTeam=teams[0];document.querySelectorAll('.team-option').forEach(b=>b.classList.toggle('active',b.dataset.team===selectedTeam));updateScout()}
function updateScout(){if(!selectedTeam)return;const rating=teamPower(selectedTeam);$('teamRating').textContent=rating;$('scoutTeam').textContent=selectedTeam;$('scoutLeague').textContent=selectedLeague;$('qualVal').textContent=rating;$('qualBar').style.width=rating+'%'}
function showScreen(name){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));$(name).classList.add('active');sceneMode=name;if(name==='home')cameraHome();if(name==='match'&&activeMatch)cameraMatch()}
function makeSchedule(){let opponents=(LEAGUES[career.league]||[]).filter(t=>t!==career.team);let schedule=[];for(let i=0;i<opponents.length;i++)schedule.push({opponent:opponents[i],home:i%2===0,played:false,score:null});return schedule}
function startCareer(){const name=$('managerName').value.trim()||'Alex Morgan';career={manager:name,team:selectedTeam,league:selectedLeague,teamPower:teamPower(selectedTeam),schedule:makeSchedule(),played:0,w:0,d:0,l:0,points:0,rep:50,table:{}};career.schedule.forEach(f=>career.table[f.opponent]={pts:0,pl:0,power:teamPower(f.opponent)});career.table[career.team]={pts:0,pl:0,power:career.teamPower};saveCareer();renderCareer();showScreen('career')}
function saveCareer(){try{localStorage.setItem('touchline27',JSON.stringify(career))}catch(e){}}
function loadCareer(){try{career=JSON.parse(localStorage.getItem('touchline27'));return !!career}catch(e){return false}}
function renderCareer(){if(!career)return;$('managerTag').textContent='MANAGER · '+career.manager.toUpperCase();$('careerClubTitle').textContent=career.team.toUpperCase();$('careerLeagueTitle').textContent=career.league+' · Season 2026/27';$('fixtureProgress').textContent=`MATCHDAY ${Math.min(career.played+1,career.schedule.length)} / ${career.schedule.length}`;$('points').textContent=career.points+' PTS';$('recordW').textContent=career.w;$('recordD').textContent=career.d;$('recordL').textContent=career.l;$('managerRep').textContent=career.rep;$('objective').textContent=career.teamPower>84?'Win the title':career.teamPower>77?'Finish in the top four':'Finish in the top half';$('playMatch').disabled=career.played>=career.schedule.length;$('playMatch').style.opacity=career.played>=career.schedule.length?'.5':'1';$('fixtures').innerHTML=career.schedule.slice(Math.max(0,career.played-1),career.played+5).map((f,j)=>{const index=Math.max(0,career.played-1)+j;let score=f.score?`${f.score[0]} — ${f.score[1]}`:'—';return `<div class="fixture-row ${index===career.played?'current':''}"><div><div class="fixture-meta">${f.played?'FULL TIME':index===career.played?'NEXT MATCH':'MATCHDAY '+(index+1)} · ${f.home?'HOME':'AWAY'}</div><div class="fixture-teams">${f.home?career.team:f.opponent} <span style="color:#718078">vs</span> ${f.home?f.opponent:career.team}</div></div><div class="fixture-result">${score}</div></div>`}).join('')||'<div class="subtle">Season complete.</div>';const standings=Object.entries(career.table).sort((a,b)=>b[1].pts-a[1].pts||b[1].power-a[1].power);$('tableRows').innerHTML=standings.slice(0,8).map(([team,s],i)=>`<div class="table-row ${team===career.team?'you':''}"><span>${i+1}</span><span>${team}</span><span>${s.pts}</span><span>${s.pl}</span></div>`).join('')}
initializeSetup();if(loadCareer())$('resumeCareer').style.display='inline-flex';
$('newCareer').onclick=()=>showScreen('setup');$('resumeCareer').onclick=()=>{renderCareer();showScreen('career')};$('launchCareer').onclick=startCareer;$('newClub').onclick=()=>showScreen('setup');document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>showScreen(b.dataset.back));

// --- Three-dimensional matchday ---
const canvas=$('scene');const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.14;
const world=new THREE.Scene();world.background=new THREE.Color('#526c63');world.fog=new THREE.FogExp2('#526c63',.0036);const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,450);const hemi=new THREE.HemisphereLight('#d8efff','#17321c',2.1);world.add(hemi);const sun=new THREE.DirectionalLight('#fff1d2',3.2);sun.position.set(-35,70,25);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;world.add(sun);
const mat=(color,rough=.8)=>new THREE.MeshStandardMaterial({color,roughness:rough});const grassMats=['#235c36','#28663a'];const lineMat=mat('#dce7d7');
function rect(parent,x,y,z,w,h,d,material){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function line(parent,points){const g=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));const l=new THREE.Line(g,new THREE.LineBasicMaterial({color:'#e4eee5',transparent:true,opacity:.8}));parent.add(l);return l}
const pitch=new THREE.Group();world.add(pitch);const ground=new THREE.Mesh(new THREE.PlaneGeometry(260,300),mat('#183b28'));ground.rotation.x=-Math.PI/2;ground.position.y=-.09;ground.receiveShadow=true;pitch.add(ground);const field=new THREE.Mesh(new THREE.PlaneGeometry(68,108),mat('#245e37'));field.rotation.x=-Math.PI/2;field.position.y=0;field.receiveShadow=true;pitch.add(field);
for(let i=0;i<10;i++){let stripe=new THREE.Mesh(new THREE.PlaneGeometry(68,10.8),mat(i%2?'#28683c':'#245e37'));stripe.rotation.x=-Math.PI/2;stripe.position.set(0,.012,-48.6+i*10.8);pitch.add(stripe)}
function fieldLine(x1,z1,x2,z2,y=.045){line(pitch,[[x1,y,z1],[x2,y,z2]])}fieldLine(-34,-54,34,-54);fieldLine(34,-54,34,54);fieldLine(34,54,-34,54);fieldLine(-34,54,-34,-54);fieldLine(-34,0,34,0);
const circlePts=[];for(let i=0;i<=64;i++){let a=i/64*Math.PI*2;circlePts.push([9.15*Math.cos(a),.048,9.15*Math.sin(a)])}line(pitch,circlePts);const centerDot=new THREE.Mesh(new THREE.CircleGeometry(.18,20),lineMat);centerDot.rotation.x=-Math.PI/2;centerDot.position.y=.05;pitch.add(centerDot);
for(const side of [-1,1]){const goalZ=side*54;fieldLine(-20,side*54,20,side*54);const boxZ=side*54-side*16.5;fieldLine(-20,boxZ,20,boxZ);fieldLine(-20,goalZ,-20,boxZ);fieldLine(20,goalZ,20,boxZ);const sixZ=side*54-side*5.5;fieldLine(-9,sixZ,9,sixZ);fieldLine(-9,goalZ,-9,sixZ);fieldLine(9,goalZ,9,sixZ);const dot=new THREE.Mesh(new THREE.CircleGeometry(.16,16),lineMat);dot.rotation.x=-Math.PI/2;dot.position.set(0,.05,side*39);pitch.add(dot);const goal=new THREE.Group();world.add(goal);for(const x of [-7.3,7.3]){const post=rect(goal,x,3.8,goalZ, .26,7.6,.26,mat('#f3f4e8'));post.castShadow=false}const cross=rect(goal,0,7.55,goalZ,14.8,.24,.25,mat('#f3f4e8'));cross.castShadow=false;const net=new THREE.Mesh(new THREE.BoxGeometry(14.5,7.3,4),new THREE.MeshBasicMaterial({color:'#e7ede2',wireframe:true,transparent:true,opacity:.15}));net.position.set(0,3.7,goalZ+side*2);goal.add(net);fieldLine(-9,side*39,9,side*39);}
// Bowl stands: four grandstands with colored crowd blocks and brilliant floodlight towers.
const standMat=mat('#182a29'),seatMats=['#415951','#52675d','#283f38','#a3ac94','#2c4e3a'];for(let side of [-1,1]){for(let row=0;row<8;row++){const z=side*(60+row*2.35);const block=rect(world,0,2.4+row*.88,z,78,2.2,2.1,mat(row%2?'#273a35':'#1f332e'));block.castShadow=false;for(let col=0;col<30;col++){if(Math.random()<.14)continue;const crowd=rect(world,-37+col*2.55,4+row*.79,z+(Math.random()-.5)*.8,.55,.65,.5,mat(seatMats[Math.floor(Math.random()*seatMats.length)]));crowd.castShadow=false;crowd.receiveShadow=false}}}
for(let side of [-1,1]){for(let xside of [-1,1]){const z=xside*43;const tower=rect(world,side*42,20,z,1.2,38,1.2,mat('#384b44'));const lamp=new THREE.PointLight('#f0f7df',115,90,2);lamp.position.set(side*42,38,z);world.add(lamp);const beam=rect(world,side*42,39,z,6,.45,2,mat('#e9f2d5'));beam.castShadow=false}}
const ballMat=mat('#f4f3e8',.34),blackMat=mat('#18211e',.38);let ball;
function makeBall(){const g=new THREE.Group();const sphere=new THREE.Mesh(new THREE.SphereGeometry(.55,20,16),ballMat);sphere.castShadow=true;g.add(sphere);for(let i=0;i<5;i++){const a=i*2*Math.PI/5;const patch=new THREE.Mesh(new THREE.CircleGeometry(.16,5),blackMat);patch.position.set(Math.cos(a)*.35,Math.sin(a)*.32,.42);patch.lookAt(new THREE.Vector3(Math.cos(a)*1.5,Math.sin(a)*1.5,1.6));g.add(patch)}world.add(g);return g}ball=makeBall();
function makePlayer(teamColor,number,isUser=false){const group=new THREE.Group();const jersey=mat(teamColor,.72),skin=mat('#bf8a64'),shorts=mat(teamColor==='#f4f4f0'?'#24363a':'#18251d'),boot=mat('#151b17');const body=new THREE.Mesh(new THREE.CapsuleGeometry(.58,.8,4,8),jersey);body.position.y=1.55;body.castShadow=true;group.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,12,10),skin);head.position.y=2.49;head.castShadow=true;group.add(head);for(let s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.65,3,6),shorts);leg.position.set(s*.23,.55,0);leg.castShadow=true;group.add(leg);const foot=rect(group,s*.23,.13,.12,.27,.15,.55,boot);foot.castShadow=true}const numberMesh=new THREE.Mesh(new THREE.CircleGeometry(.25,12),mat(isUser?'#c8fa51':'#ffffff'));numberMesh.position.set(0,1.55,.59);group.add(numberMesh);if(isUser){const ring=new THREE.Mesh(new THREE.RingGeometry(.65,.78,32),new THREE.MeshBasicMaterial({color:'#c8fa51',side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.06;group.add(ring);const arrow=new THREE.Mesh(new THREE.ConeGeometry(.22,.55,3),new THREE.MeshBasicMaterial({color:'#c8fa51'}));arrow.position.y=3.1;group.add(arrow)}group.userData={isUser,number,speed:Math.random()*.15+.96,team:teamColor};world.add(group);return group}
function cameraHome(){camera.position.set(54,48,68);camera.lookAt(0,0,0)}function cameraMatch(){if(!activeMatch)return;camera.position.set(activeMatch.player.position.x*.55,17,activeMatch.player.position.z-23);camera.lookAt(activeMatch.player.position.x*.38,0,activeMatch.player.position.z+9)}cameraHome();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
function addToast(text){const t=$('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1350)}
function newMatch(){if(!career||career.played>=career.schedule.length)return;const fixture=career.schedule[career.played];let homeName=fixture.home?career.team:fixture.opponent,awayName=fixture.home?fixture.opponent:career.team;activeMatch={fixture,homeName,awayName,homeScore:0,awayScore:0,elapsed:0,duration:82,clock:0,paused:false,finished:false,homeColor:crestColor(homeName),awayColor:crestColor(awayName),players:[],ballVelocity:new THREE.Vector3(),possession:'home',player:null,teamMates:[],opponents:[],lastCpuShot:0};
// Ten outfield players each, arranged in an organic 4-3-3 shape.
const homeTeam=[];const awayTeam=[];for(let i=0;i<10;i++){const x=((i%4)-1.5)*12+(Math.random()-.5)*2,z=-37+Math.floor(i/4)*9;let p=makePlayer(activeMatch.homeColor,i+1,false);p.position.set(x,0,z);homeTeam.push(p)}for(let i=0;i<10;i++){const x=((i%4)-1.5)*12+(Math.random()-.5)*2,z=37-Math.floor(i/4)*9;let p=makePlayer(activeMatch.awayColor,i+1,false);p.position.set(x,0,z);awayTeam.push(p)}
// The manager directly controls one outfield player for an immediate, hands-on match.
const controlled=makePlayer(activeMatch.homeColor,10,true);controlled.position.set(-3,0,-18);homeTeam.push(controlled);activeMatch.player=controlled;activeMatch.teamMates=homeTeam.filter(p=>p!==controlled);activeMatch.opponents=awayTeam;activeMatch.players=[...homeTeam,...awayTeam];
// If the selected club plays away, preserve its kit and home/away scoreboard identity; the controlled club always attacks toward the far end.
$('homeLabel').textContent=career.team.split(' ').slice(-1)[0].toUpperCase();$('awayLabel').textContent=fixture.opponent.split(' ').slice(-1)[0].toUpperCase();$('scoreHome').textContent='0';$('scoreAway').textContent='0';$('matchClock').textContent='00:00';$('matchOverlay').classList.remove('show');$('pauseMatch').textContent='Ⅱ  PAUSE';ball.position.set(0,.56,-17);activeMatch.ballCarrier=controlled;activeMatch.lastTouch=controlled;activeMatch.lastCpuShot=-5;showScreen('match');clockLast=performance.now()}
function nearestPlayer(group,pos){let best=null,dist=Infinity;for(const p of group){const d=p.position.distanceTo(pos);if(d<dist){dist=d;best=p}}return best}
